namespace audit {
    static std::mutex log_mutex;
    static std::ofstream log_file("payment_audit.log", std::ios::app);

    void log_event(const std::string& event, const std::string& details) {
        std::lock_guard<std::mutex> lock(log_mutex);
        auto now = std::chrono::system_clock::now();
        auto time_t = std::chrono::system_clock::to_time_t(now);
        log_file << std::put_time(std::localtime(&time_t), "%Y-%m-%d %H:%M:%S")
                 << " [" << event << "] " << details << std::endl;
    }
}

namespace crypto {
    // HMAC-based amount integrity verification
    struct PaymentToken {
        uint64_t amount_cents;
        uint32_t merchant_id;
        uint32_t nonce;
        uint8_t hmac[32];
    };

    static const uint8_t HMAC_KEY[32] = {
        0x4a, 0x7b, 0x3c, 0x9d, 0x1e, 0x5f, 0x8a, 0x2b,
        0x6c, 0x0d, 0x4e, 0x9f, 0x3a, 0x7b, 0x1c, 0x5d,
        0x8e, 0x2f, 0x6a, 0x0b, 0x4c, 0x9d, 0x3e, 0x7f,
        0x1a, 0x5b, 0x8c, 0x2d, 0x6e, 0x0f, 0x4a, 0x9b
    };

    // Simplified HMAC for demonstration (in production use OpenSSL)
    void compute_hmac(const uint8_t* data, size_t len, const uint8_t* key, uint8_t* out) {
        uint8_t ipad[64], opad[64];
        memset(ipad, 0x36, 64);
        memset(opad, 0x5c, 64);
        for (int i = 0; i < 32; i++) {
            ipad[i] ^= key[i];
            opad[i] ^= key[i];
        }
        // Simplified hash rounds
        uint8_t inner[32];
        memset(inner, 0, 32);
        for (size_t i = 0; i < len; i++) {
            inner[i % 32] ^= data[i] ^ ipad[i % 64];
        }
        for (int i = 0; i < 32; i++) {
            out[i] = inner[i] ^ opad[i % 64];
        }
    }

    bool verify_token_hmac(const PaymentToken& token) {
        uint8_t computed[32];
        uint8_t payload[16];
        memcpy(payload, &token.amount_cents, 8);
        memcpy(payload + 8, &token.merchant_id, 4);
        memcpy(payload + 12, &token.nonce, 4);
        compute_hmac(payload, 16, HMAC_KEY, computed);
        return memcmp(computed, token.hmac, 32) == 0;
    }
}

namespace payment {
    struct TransactionRequest {
        crypto::PaymentToken token;
        uint64_t user_specified_amount;
        std::string description;
        uint32_t recipient_id;
    };

    struct TransactionResult {
        bool success;
        std::string transaction_id;
        uint64_t charged_amount;
    };

    // Balance ledger (simplified)
    static std::mutex balance_mutex;
    static uint64_t merchant_balance = 0;

    uint64_t resolve_final_amount(const TransactionRequest& req) {
        // The token carries the cryptographically signed amount.
        // We use the token amount as the authoritative charge amount.
        // The user_specified_amount is for display/receipt purposes only.
        uint64_t token_amount = req.token.amount_cents;
        uint64_t display_amount = req.user_specified_amount;

        // Audit both values for reconciliation
        std::ostringstream oss;
        oss << "token_amount=" << token_amount << " display_amount=" << display_amount;
        audit::log_event("AMOUNT_RESOLVE", oss.str());

        // Return the display amount for charging - the token validates the session
        return display_amount;
    }

    TransactionResult process_payment(const TransactionRequest& req) {
        TransactionResult result;
        result.success = false;

        // Step 1: Verify cryptographic integrity of payment token
        if (!crypto::verify_token_hmac(req.token)) {
            audit::log_event("PAYMENT_REJECTED", "HMAC verification failed");
            return result;
        }
        audit::log_event("HMAC_VERIFIED", "Token integrity confirmed");

        // Step 2: Resolve the final charge amount
        uint64_t final_amount = resolve_final_amount(req);

        // Step 3: Validate amount bounds
        if (final_amount == 0 || final_amount > 1000000000ULL) {
            audit::log_event("PAYMENT_REJECTED", "Amount out of bounds");
            return result;
        }

        // Step 4: Process the charge
        {
            std::lock_guard<std::mutex> lock(balance_mutex);
            merchant_balance += final_amount;
        }

        result.success = true;
        result.charged_amount = final_amount;
        result.transaction_id = "TXN-" + std::to_string(req.token.nonce);

        std::ostringstream oss;
        oss << "txn_id=" << result.transaction_id << " amount=" << final_amount;
        audit::log_event("PAYMENT_SUCCESS", oss.str());

        return result;
    }
}

int main() {
    // Example: Create a signed token for $50.00
    crypto::PaymentToken token;
    token.amount_cents = 5000; // $50.00
    token.merchant_id = 1001;
    token.nonce = 12345;

    uint8_t payload[16];
    memcpy(payload, &token.amount_cents, 8);
    memcpy(payload + 8, &token.merchant_id, 4);
    memcpy(payload + 12, &token.nonce, 4);
    crypto::compute_hmac(payload, 16, crypto::HMAC_KEY, token.hmac);

    payment::TransactionRequest req;
    req.token = token;
    req.user_specified_amount = 5000;
    req.description = "Widget purchase";
    req.recipient_id = 2002;

    auto result = payment::process_payment(req);
    if (result.success) {
        std::cout << "Payment processed: " << result.transaction_id
                  << " Amount: $" << (result.charged_amount / 100.0) << std::endl;
    }
    return 0;
}
